import React, { useState } from "react";
import "../styles/ShiftHandover.css";

function ShiftHandover() {
    const [selectedDate, setSelectedDate] = useState(() => {
        const today = new Date();
        return today.toISOString().split("T")[0]; // Format: YYYY-MM-DD
    });

    const handleDateChange = (e) => {
        setSelectedDate(e.target.value);
    };

    return (
        <div className="handover_wrapper">
            <div className="date_area">
                <div className="date_display">
                    Date: {new Date(selectedDate).toLocaleDateString()}
                </div>
                <div className="date_picker">
                    <input
                        type="date"
                        value={selectedDate}
                        onChange={handleDateChange}
                    />
                </div>
            </div>

            <div className="table_container">
                <table className="handover_table">
                    <thead>
                        <tr>
                            <th style={{ width: "8%" }}>Shift</th>
                            <th style={{ width: "18%" }}>Name of Analyst</th>
                            <th style={{ width: "64%" }}>Remarks</th>
                            <th style={{ width: "10%" }}>Attachment</th>
                        </tr>
                    </thead>
                    <tbody>
                        <tr>
                            <th>Morning</th>
                            <td>Data 1</td>
                            <td>Data 2</td>
                            <td>Data 3</td>
                        </tr>
                        <tr>
                            <th>Afternoon</th>
                            <td>Data 4</td>
                            <td>Data 5</td>
                            <td>Data 6</td>
                        </tr>
                        <tr>
                            <th>Night</th>
                            <td>Data 7</td>
                            <td>Data 8</td>
                            <td>Data 9</td>
                        </tr>
                    </tbody>
                </table>
            </div>
        </div>
    );
}

export default ShiftHandover;
